-- AEMS Pilot Student Load
-- Source: AVF July 2026 attendance data
-- Pilot CCs: MACHERLA ANITHA and SARITHA
-- Pilot centres: 26AG08, 26AG09, 26AG10, 26KP06, 26KP07, 26KP08
-- Minimum fields loaded: student_code, student_name, gender, center_id
-- No historical attendance is loaded by this script.

BEGIN;

-- Validate that all six pilot centres exist.
DO $$
DECLARE
    missing_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO missing_count FROM (VALUES ('26AG08'), ('26AG09'), ('26AG10'), ('26KP06'), ('26KP07'), ('26KP08')) AS p(center_code)
    WHERE NOT EXISTS (
        SELECT 1 FROM public.tuition_center tc
        WHERE tc.center_code = p.center_code
    );
    IF missing_count > 0 THEN
        RAISE EXCEPTION 'One or more pilot centres are missing from tuition_center';
    END IF;
END $$;

-- Load/update only the six pilot centres.

-- Verification
SELECT tc.center_code, COUNT(sm.student_id) AS student_count
FROM public.tuition_center tc
LEFT JOIN public.student_master sm
  ON sm.center_id = tc.center_id
 AND sm.active_flag = TRUE
WHERE tc.center_code IN ('26AG08','26AG09','26AG10','26KP06','26KP07','26KP08')
GROUP BY tc.center_code
ORDER BY tc.center_code;

COMMIT;